export function pixelRects(p: Pixels) {
	return p.rects.split(" ").map((r) => {
		const [x, y, w, h, c] = r.split(",").map(Number) as [
			number,
			number,
			number,
			number,
			number,
		];
		return { x, y, w, h, fill: p.palette[c] as string };
	});
}

